## 2. Use-Case-Interface-Components

In `unifiedmandala-ui`, bauen wir wiederverwendbare React-Komponenten, die aus Go-Usecase-Responses interaktive Widgets machen.

```tsx
// components/GPTPanel.tsx
import React, { useState } from "react"
import { Button, Textarea } from "@/components/ui"
import { invoke } from "@/lib/api" // Next.js / fetch wrapper

export function GPTPanel() {
  const [input, setInput] = useState("")
  const [output, setOutput] = useState<string>()
  const [mode, setMode] = useState<"api"|"link">("api")

  const handleRun = async () => {
    const route = mode === "api" ? "/gpt/ask" : "/gpt/link"
    const res = await invoke(route, { prompt: input })
    setOutput(res.text)
  }

  return (
    <div className="p-4 border rounded-lg">
      <div className="mb-2">
        <Button onClick={() => setMode("api")} variant={mode==="api"?"primary":"outline"}>GPT-API</Button>
        <Button onClick={() => setMode("link")} variant={mode==="link"?"primary":"outline"}>GPT-Link</Button>
      </div>
      <Textarea
        rows={4}
        placeholder={mode==="api"?"Enter prompt…":"Enter URL…"}
        value={input}
        onChange={e => setInput(e.target.value)}
      />
      <Button onClick={handleRun} className="mt-2">Run</Button>
      {output && (
        <pre className="mt-4 p-2 bg-gray-50 rounded">{output}</pre>
      )}
    </div>
  )
}
```

