### 2. Gemeinsamer GPT-Client (`pkg/codeagent/common/client.go`)

```go
package common

import (
  "context"
  "encoding/json"
  "net/http"
  "bytes"
)

type Client struct {
  Endpoint, APIKey string
}

func NewClient(endpoint, apiKey string) *Client {
  return &Client{Endpoint: endpoint, APIKey: apiKey}
}

func (c *Client) Ask(ctx context.Context, prompt string) (string, error) {
  reqBody, _ := json.Marshal(map[string]string{"prompt": prompt})
  req, _ := http.NewRequestWithContext(ctx, "POST", c.Endpoint, bytes.NewReader(reqBody))
  req.Header.Set("Authorization", "Bearer "+c.APIKey)
  req.Header.Set("Content-Type", "application/json")
  resp, err := http.DefaultClient.Do(req)
  if err != nil { return "", err }
  defer resp.Body.Close()
  var result struct{ Text string }
  if err := json.NewDecoder(resp.Body).Decode(&result); err != nil {
    return "", err
  }
  return result.Text, nil
}
```

### 3. Python Agent (`pkg/codeagent/python_agent/client.go`)

```go
package python_agent

import (
  "context"
  "fmt"
  "github.com/GenesisAeon/unifiedmandala/go-bridge/pkg/codeagent/common"
)

type Request struct{ Description string }
type Response struct{ Code string }

type PythonAgent struct{ client *common.Client }

func NewPythonAgent(ep, key string) *PythonAgent {
  return &PythonAgent{client: common.NewClient(ep, key)}
}

// GenerateSnippet erzeugt einen Python-Code-Schnipsel
func (a *PythonAgent) GenerateSnippet(ctx context.Context, req Request) (Response, error) {
  prompt := fmt.Sprintf("Generate a Python function for: %s", req.Description)
  code, err := a.client.Ask(ctx, prompt)
  return Response{Code: code}, err
}
```

